/** Internal move factory. */
function makeMove(from, to, piece, captured, capturedSq, promotion, flags) {
  return {
    from,
    to,
    piece,
    captured: captured || 0,
    capturedSq,
    promotion: promotion || 0,
    flags: flags | (captured ? F_CAPTURE : 0),
  };
}

/** UCI text for a move ("e2e4", "e7e8q"). */
